paragraph.math:
$$\begin{matrix}
      \left\langle p\text{,~}q \right\rangle & = & {p(0)q(0) + p\left( \frac{1}{2} \right)q\left( \frac{1}{2} \right) + p(1)q(1)} \\
       & = & {(0)( - 1) + (3)(0) + (12)(1) = 12} \\
      \left\langle q\text{,~}q \right\rangle & = & {\left\lbrack q(0) \right\rbrack^{2} + \left\lbrack q\left( \frac{1}{2} \right) \right\rbrack^{2} + \left\lbrack q(1) \right\rbrack^{2}} \\
       & = & {\left( {- 1} \right)^{2} + (0)^{2} + (1)^{2}}
      \end{matrix}$$

$$\begin{array}{rrr}
      {\widehat{p} = \text{proj}_{\mathbf{P}_{2}}p} & = & {\frac{\left\langle p\text{,~}p_{0} \right\rangle}{\left\langle p_{0}\text{,~}p_{0} \right\rangle}p_{0} + \frac{\left\langle p\text{,~}p_{1} \right\rangle}{\left\langle p_{1}\text{,~}p_{1} \right\rangle}p_{1} + \frac{\left\langle p\text{,~}p_{2} \right\rangle}{\left\langle p_{2}\text{,~}p_{2} \right\rangle}p_{2}} \\
       & = & {\frac{8}{5}p_{0} + \frac{- 31}{14}p_{2} = \frac{8}{5} - \frac{31}{14}\left( t^{2} - 2 \right).}
      \end{array}$$

$$\begin{matrix}
      \left\langle p_{3}\text{,~}q_{1} \right\rangle & = & {\int_{0}^{1}12t^{2} \cdot 1 dt = 4t^{3}|_{0}^{1} = 4} \\
      \left\langle q_{1}\text{,~}q_{1} \right\rangle & = & {\int_{0}^{1}1 \cdot 1 dt = t|_{0}^{1} = 1} \\
      \left\langle p_{3}\text{,~}q_{2} \right\rangle & = & {\int_{0}^{1}12t^{2}\text{(}2t - 1\text{)} dt = \int_{0}^{1}\text{(}24t^{3} - 12t^{2}\text{)} dt = 2} \\
      \left\langle q_{2}\text{,~}q_{2} \right\rangle & = & {\int_{0}^{1}{\text{(}2t - 1\text{)}}^{2} dt = \frac{1}{6}{\text{(}2t - 1\text{)}}^{3}|_{0}^{1} = \frac{1}{3}}
      \end{matrix}$$

statement.paragraph:
Given $a \geq 0$ and $b \geq 0$, let $\mathbf{u} = \left\lbrack \begin{array}{r}
      \sqrt{a} \\
      \sqrt{b}
      \end{array} \right\rbrack$ and $\mathbf{v} = \left\lbrack \begin{array}{r}
      \sqrt{b} \\
      \sqrt{a}
      \end{array} \right\rbrack$. Use the Cauchy–Schwarz inequality to compare the geometric mean $\sqrt{ab}$ with the arithmetic mean $(a + b)/2$.
